function rebuildContent(tokens) {
  return tokens.map((t) => {
    if (t.type === "variable") {
      return `{{${t.rawString}}}`;
    }
    if (t.type === "expression") {
      return `@{${t.rawString}}`;
    }
    return t.rawString;
  }).join("");
}
function validateSchemaFieldName(kind, name) {
  const normalized = name.trim();
  if (normalized.length === 0) {
    throw new Error(`${kind} name cannot be empty`);
  }
  if (!PROMPT_VARIABLE_NAME_PATTERN.test(normalized)) {
    throw new Error(`${kind} name can only contain letters, numbers, underscores, dots, and hyphens`);
  }
  return normalized;
}
function validateToolName(resources, name) {
  return validateResourceName(resources, "tool", "Tool", name);
}
function validateResourceName(resources, resourceType, kind, name) {
  const normalizedName = name.trim();
  if (normalizedName.length === 0) {
    throw new Error(`${kind} name cannot be empty`);
  }
  const duplicate = (resources ?? []).find((resource) => resource.$resourceType === resourceType && resource.name.trim() === normalizedName);
  if (duplicate) {
    throw new Error(`${kind} "${normalizedName}" already exists`);
  }
  return normalizedName;
}

