var DEFAULT_TIMEOUT_MS2 = 600000;
function parsePositiveNumber(value, flag) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error(`${flag} must be a positive number.`);
  }
  return parsed;
}
var registerDebugCommand = (program2) => {
  program2.command("debug").description("Debug a low-code agent by running it on Studio Web and streaming the result").argument("<project-path>", "Path to the agent project directory (containing agent.json)").option("-i, --inputs <json>", `Input arguments as JSON string (e.g. '{"input":"hello"}')`).option("--poll-interval <ms>", "Polling interval in milliseconds", "2000").option("--timeout <seconds>", "Maximum seconds to wait for the debug run to finish").option("--login-validity <minutes>", "Minimum minutes before token expiration", (v) => Number.parseInt(v, 10), 10).examples(AGENT_DEBUG_EXAMPLES).trackedAction(processContext, async (projectPath, options) => {
    const [error, result] = await catchError((async () => {
      const loginStatus2 = await getLoginStatusAsync({
        ensureTokenValidityMinutes: options.loginValidity
      });
      if (loginStatus2.loginStatus !== "Logged in" || !loginStatus2.accessToken || !loginStatus2.baseUrl || !loginStatus2.organizationId) {
        throw new Error("Not logged in. Run 'uip login' first.");
      }
      const tenantName = loginStatus2.tenantName;
      if (!tenantName) {
        throw new Error("Tenant must be selected during login. Run 'uip login' or 'uip login tenant set <tenant>'.");
      }
      let inputs = {};
      if (options.inputs !== undefined) {
        const [parseError, parsed] = catchError(() => JSON.parse(options.inputs));
        if (parseError || typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
          throw new Error(`--inputs must be a JSON object: ${options.inputs}`);
        }
        inputs = parsed;
      }
      const pollIntervalMs = parsePositiveNumber(options.pollInterval ?? "2000", "--poll-interval");
      const maxPolls = options.timeout !== undefined ? Math.max(1, Math.ceil(parsePositiveNumber(options.timeout, "--timeout") * 1000 / pollIntervalMs)) : Math.ceil(DEFAULT_TIMEOUT_MS2 / pollIntervalMs);
      const auth = {
        baseUrl: loginStatus2.baseUrl,
        accessToken: loginStatus2.accessToken,
        organizationId: loginStatus2.organizationId,
        tenantName
      };
      return new AgentDebugService().debug({
        projectPath,
        inputs,
        pollIntervalMs,
        maxPolls,
        onState: (state) => OutputFormatter.log({
          Message: `State: ${state}`
        })
      }, auth);
    })());
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to debug agent",
        Instructions: error.message
      });
      processContext.exit(1);
      return;
    }
    const data = {
      State: result.finalState,
      TraceId: result.traceId,
      JobKey: result.jobKey
    };
    if (result.output !== undefined) {
      data.Output = result.output;
    }
    if (result.info) {
      data.Info = result.info;
    }
    if (result.success) {
      OutputFormatter.success({
        Result: RESULTS.Success,
        Code: "AgentDebug",
        Data: data,
        Instructions: `Debug run completed: ${result.finalState}`
      });
      return;
    }
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Code: "AgentDebug",
      Message: `Debug run ${result.finalState}.`,
      Instructions: `Inspect the run with: uip traces spans get ${result.traceId}`,
      Data: data
    });
    processContext.exit(1);
  });
};

