var registerDeployCommand = (program2) => {
  program2.command("deploy").description("Deploy a published agent solution to Orchestrator (creates folder, process, and connections)").argument("<packageVersionKey>", "Package version key from 'agent publish' output").option("-n, --name <name>", "Deployment name (default: package name)").option("--folder-key <guid>", "Installation folder key (GUID). If omitted, a new folder is auto-created.").option("--force-activate", "Force activation even if previous deployment exists").option("--skip-activate", "Stop after install (do not activate)").addOption(createHiddenDeprecatedTenantOption("-t, --tenant <tenant>")).option("--timeout <seconds>", "Timeout for each deployment step in seconds", (v) => Number.parseInt(v, 10), 120).option("--login-validity <minutes>", "Minimum minutes before token expiration", (v) => Number.parseInt(v, 10), 10).examples(DEPLOY_EXAMPLES).trackedAction(processContext, async (packageVersionKey, options) => {
    const [error] = await catchError((async () => {
      const loginStatus2 = await getLoginStatusAsync({
        ensureTokenValidityMinutes: options.loginValidity
      });
      if (loginStatus2.loginStatus !== "Logged in" || !loginStatus2.accessToken || !loginStatus2.baseUrl || !loginStatus2.organizationId) {
        throw new Error("Not logged in. Run 'uip login' first.");
      }
      const tenantName = options.tenant ?? loginStatus2.tenantName;
      if (!tenantName) {
        throw new Error("Tenant must be selected during login. Run 'uip login' or 'uip login tenant set <tenant>'.");
      }
      const basePath = `${loginStatus2.baseUrl}/${loginStatus2.organizationId}/${tenantName}/automationsolutions_`;
      const configuration = new Configuration3({
        basePath,
        accessToken: loginStatus2.accessToken
      });
      const headers2 = {
        Authorization: `Bearer ${loginStatus2.accessToken}`,
        "Content-Type": "application/json"
      };
      const timeoutMs = options.timeout * 1000;
      OutputFormatter.log({
        Message: "Creating configuration..."
      });
      const configApi = new ConfigurationsApi(configuration);
      const configurationKey = await configApi.configurationsPost({
        createConfigurationCommand: {
          packageVersionKey
        }
      });
      OutputFormatter.log({
        Message: `Configuration: ${configurationKey}`
      });
      const deploymentName = options.name ?? `agent-${Date.now()}`;
      OutputFormatter.log({
        Message: `Creating deployment "${deploymentName}"...`
      });
      const deploymentsApi = new DeploymentsApi(configuration);
      const deployment = await deploymentsApi.deploymentsPost({
        deploymentRequest: {
          configurationKey,
          deploymentName,
          installationFolderKey: options.folderKey,
          forceActivate: options.forceActivate
        }
      });
      const deploymentKey = deployment.key;
      OutputFormatter.log({ Message: "Installing..." });
      const runResp = await fetch(`${basePath}/api/deployments/${encodeURIComponent(deploymentKey)}/run`, { method: "POST", headers: headers2 });
      if (!runResp.ok) {
        throw new Error(`Deploy run failed: ${runResp.status} ${await runResp.text()}`);
      }
      const runData = await runResp.json();
      const installPoll = await pollDeployment(basePath, loginStatus2.accessToken, deploymentKey, "install", timeoutMs);
      if (installPoll.outcome !== PollOutcome.Completed) {
        throw new DeployPollError(installPoll.outcome);
      }
      if (!installPoll.data) {
        throw new Error("Poll completed but returned no data");
      }
      const installResult = installPoll.data;
      if (installResult.status === "FailedInstall") {
        throw new Error("Deployment install failed. Check Orchestrator for details.");
      }
      OutputFormatter.log({
        Message: `Installed → folder: ${installResult.installedRootFolderName ?? "auto"}`
      });
      let provisionedFolderId;
      const installedFolderKey = installResult.installedRootFolderKey;
      if (installedFolderKey) {
        const orchOptions = {
          tenant: tenantName,
          loginValidity: options.loginValidity
        };
        OutputFormatter.log({
          Message: "Provisioning folder for agent execution..."
        });
        const [provError, provResult] = await catchError(provisionFolder(installedFolderKey, orchOptions));
        if (provError) {
          OutputFormatter.log({
            Message: `Warning: Auto-provisioning incomplete (${provError.message}). Assign a serverless machine and robot user to the folder manually.`
          });
        } else if (provResult) {
          provisionedFolderId = provResult.folderId;
          OutputFormatter.log({
            Message: `Provisioned: machine "${provResult.machineName}", user "${provResult.userName}" → folder ${provResult.folderId}`
          });
        }
      }
      if (!options.skipActivate && installResult.activationStatus === "ReadyToActivate") {
        OutputFormatter.log({ Message: "Activating..." });
        const instanceId = runData.instanceId ?? installResult.instanceId ?? "";
        if (!instanceId) {
          throw new Error("Deployment is ready to activate but no instance ID was returned.");
        }
        const activateResp = await fetch(`${basePath}/api/deployments/${deploymentKey}/activate?instanceId=${encodeURIComponent(instanceId)}`, { method: "POST", headers: headers2 });
        if (!activateResp.ok) {
          throw new Error(`Activate failed: ${activateResp.status} ${await activateResp.text()}`);
        }
        const activatePoll = await pollDeployment(basePath, loginStatus2.accessToken, deploymentKey, "activate", timeoutMs);
        if (activatePoll.outcome !== PollOutcome.Completed) {
          throw new DeployPollError(activatePoll.outcome);
        }
        if (!activatePoll.data) {
          throw new Error("Poll completed but returned no data");
        }
        const activateResult = activatePoll.data;
        if (activateResult.status === "FailedActivate") {
          throw new Error("Deployment activation failed. Check Orchestrator for details.");
        }
        OutputFormatter.success({
          Result: RESULTS.Success,
          Code: "AgentDeploy",
          Data: {
            DeploymentKey: deploymentKey,
            DeploymentName: deploymentName,
            Status: activateResult.status,
            FolderKey: activateResult.installedRootFolderKey,
            FolderId: provisionedFolderId,
            FolderName: activateResult.installedRootFolderName,
            ConfigurationKey: configurationKey,
            PackageVersionKey: packageVersionKey
          },
          Instructions: provisionedFolderId ? `Deployment active and provisioned. Run: agent run list --folder-id ${provisionedFolderId}` : "Deployment active. Use 'agent run list --folder-id <id>' to find releases, then 'agent run start' to run."
        });
        trackShipSucceeded({
          ship_kind: "deploy",
          target: "orchestrator",
          project_type: "low_code_agent",
          command_name: "uip.agent.deploy",
          artifact_correlation_key: deploymentKey,
          deployment_key: deploymentKey,
          package_version_key: packageVersionKey,
          folder_key: activateResult.installedRootFolderKey
        });
      } else {
        OutputFormatter.success({
          Result: RESULTS.Success,
          Code: "AgentDeploy",
          Data: {
            DeploymentKey: deploymentKey,
            DeploymentName: deploymentName,
            Status: installResult.status,
            FolderKey: installResult.installedRootFolderKey,
            FolderId: provisionedFolderId,
            ConfigurationKey: configurationKey,
            PackageVersionKey: packageVersionKey
          },
          Instructions: options.skipActivate ? `Installed${provisionedFolderId ? " and provisioned" : ""} but not activated. Activate manually or re-run without --skip-activate.` : `Deployment installed${provisionedFolderId ? " and provisioned" : ""}. Activate when ready.`
        });
        trackShipSucceeded({
          ship_kind: "deploy",
          target: "orchestrator",
          project_type: "low_code_agent",
          command_name: "uip.agent.deploy",
          artifact_correlation_key: deploymentKey,
          deployment_key: deploymentKey,
          package_version_key: packageVersionKey,
          folder_key: installResult.installedRootFolderKey
        });
      }
    })());
    if (error) {
      const exitCode = error instanceof DeployPollError ? error.exitCode : 1;
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to deploy agent",
        Instructions: error.message
      });
      processContext.exit(exitCode);
    }
  });
};

