function formatEvalRunRow(r, evaluators, verbose = false) {
  let evalScores = "-";
  let justifications = "-";
  if (r.assertionRuns && r.assertionRuns.length > 0) {
    const parts = r.assertionRuns.map((a) => {
      const ev = evaluators.find((e) => e.id === a.evaluatorId);
      const name = ev?.name ?? a.evaluatorId;
      const scoreObj = a.result?.score;
      if (String(scoreObj?.type) === "error") {
        return `${name}: Error`;
      }
      const score = scoreObj?.value;
      return `${name}: ${score ?? "-"}`;
    });
    evalScores = parts.join(", ");
    if (verbose) {
      const justParts = r.assertionRuns.filter((a) => a.result?.score?.justification).map((a) => {
        const ev = evaluators.find((e) => e.id === a.evaluatorId);
        const name = ev?.name ?? a.evaluatorId;
        return `[${name}] ${a.result?.score?.justification}`;
      });
      if (justParts.length > 0) {
        justifications = justParts.join(" | ");
      }
    }
  } else if (r.result?.evaluatorScores && r.result.evaluatorScores.length > 0) {
    const parts = r.result.evaluatorScores.map((s) => {
      const ev = evaluators.find((e) => e.id === s.evaluatorId);
      return `${ev?.name ?? s.evaluatorId}: ${s.value}`;
    });
    evalScores = parts.join(", ");
    if (verbose) {
      const justParts = r.result.evaluatorScores.filter((s) => s.justification).map((s) => {
        const ev = evaluators.find((e) => e.id === s.evaluatorId);
        const name = ev?.name ?? s.evaluatorId;
        return `[${name}] ${s.justification}`;
      });
      if (justParts.length > 0) {
        justifications = justParts.join(" | ");
      }
    }
  }
  const tokens = r.completionMetrics?.tokens;
  const tokenDisplay = tokens && tokens > 0 ? tokens : "-";
  const row = {
    TestCase: r.evalSnapshot?.name ?? r.id,
    Status: r.status,
    Score: r.result?.score?.value ?? "-",
    EvaluatorScores: evalScores,
    Tokens: tokenDisplay,
    Duration: r.completionMetrics?.duration ? `${(r.completionMetrics.duration / 1000).toFixed(1)}s` : "-",
    Error: r.errorMessage ?? "-"
  };
  if (verbose) {
    row.Justifications = justifications;
  }
  return row;
}
function isFailedRun(r) {
  const status = String(r.status);
  if (status === "failed" || status === "3")
    return true;
  if (r.errorMessage)
    return true;
  if (r.result?.score?.type !== undefined) {
    if (String(r.result.score.type) === "error" || String(r.result.score.type) === "2") {
      return true;
    }
  }
  if (r.assertionRuns?.some((a) => String(a.result?.score?.type) === "error" || String(a.result?.score?.type) === "2")) {
    return true;
  }
  if (r.assertionRuns?.some((a) => a.result?.score?.value === false)) {
    return true;
  }
  return false;
}
