function flattenStructure(folder, prefix) {
  const entries = [];
  const currentPath = prefix ? `${prefix}/${folder.name}` : folder.name;
  for (const file of folder.files ?? []) {
    entries.push({
      Path: `${currentPath}/${file.name}`,
      Id: file.id,
      Name: file.name,
      FileType: file.fileType ?? "",
      IsMain: String(file.isMain ?? false),
      IsEntryPoint: String(file.isEntryPoint ?? false)
    });
  }
  for (const sub2 of folder.folders ?? []) {
    entries.push(...flattenStructure(sub2, currentPath));
  }
  return entries;
}
async function getAuthAndBackendBase(loginValidity) {
  const loginStatus2 = await getLoginStatusAsync({
    ensureTokenValidityMinutes: loginValidity
  });
  if (loginStatus2.loginStatus !== "Logged in" || !loginStatus2.accessToken || !loginStatus2.baseUrl || !loginStatus2.organizationId) {
    throw new Error("Not logged in. Run 'uip login' first.");
  }
  const backendBase = `${loginStatus2.baseUrl}/${loginStatus2.organizationId}/studio_/backend`;
  return { loginStatus: loginStatus2, backendBase };
}
var registerFilesCommands = (program2) => {
  const file = program2.command("file").description("Manage project files in Studio Web");
  file.command("list").description("List files in a Studio Web project").argument("<projectId>", "Project UUID").option("--login-validity <minutes>", "Minimum minutes before token expiration", (v) => Number.parseInt(v, 10), 10).examples(FILE_LIST_EXAMPLES).trackedAction(processContext, async (projectId, options) => {
    const [error] = await catchError((async () => {
      const { loginStatus: loginStatus2, backendBase } = await getAuthAndBackendBase(options.loginValidity);
      const url = `${backendBase}/api/Project/${projectId}/FileOperations/Structure`;
      const response = await fetch(url, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${loginStatus2.accessToken}`
        }
      });
      if (!response.ok) {
        const text = await response.text();
        throw new Error(`Studio Web API returned ${response.status}: ${text}`);
      }
      const structure = await response.json();
      const entries = flattenStructure(structure, "");
      if (entries.length === 0) {
        OutputFormatter.success({
          Result: RESULTS.Success,
          Code: "AgentFileList",
          Data: {
            Message: "No files found in project"
          }
        });
        return;
      }
      OutputFormatter.success({
        Result: RESULTS.Success,
        Code: "AgentFileList",
        Data: entries
      });
    })());
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to list project files",
        Instructions: error.message
      });
      processContext.exit(1);
    }
  });
  file.command("get").description("Download a file from a Studio Web project").argument("<projectId>", "Project UUID").argument("<fileId>", "File UUID").option("-d, --destination <path>", "Destination file path (default: write to stdout)").option("--login-validity <minutes>", "Minimum minutes before token expiration", (v) => Number.parseInt(v, 10), 10).examples(FILE_GET_EXAMPLES).trackedAction(processContext, async (projectId, fileId, options) => {
    const [error] = await catchError((async () => {
      const { loginStatus: loginStatus2, backendBase } = await getAuthAndBackendBase(options.loginValidity);
      const url = `${backendBase}/api/Project/${projectId}/FileOperations/File/${fileId}`;
      const response = await fetch(url, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${loginStatus2.accessToken}`
        }
      });
      if (!response.ok) {
        const text = await response.text();
        throw new Error(`Studio Web API returned ${response.status}: ${text}`);
      }
      const arrayBuffer = await response.arrayBuffer();
      const buffer = Buffer.from(arrayBuffer);
      const fs7 = getFileSystem();
      if (options.destination) {
        const outputPath = fs7.path.resolve(options.destination);
        const parentDir = fs7.path.dirname(outputPath);
        await fs7.mkdir(parentDir);
        await fs7.writeFile(outputPath, buffer);
        OutputFormatter.success({
          Result: RESULTS.Success,
          Code: "AgentFileGet",
          Data: {
            Status: "File downloaded",
            ProjectId: projectId,
            FileId: fileId,
            Output: outputPath
          }
        });
      } else {
        OutputFormatter.success({
          Result: RESULTS.Success,
          Code: "AgentFileGet",
          Data: {
            Status: "File downloaded",
            ProjectId: projectId,
            FileId: fileId,
            Content: buffer.toString("base64"),
            Encoding: "base64"
          }
        });
      }
    })());
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to download file",
        Instructions: error.message
      });
      processContext.exit(1);
    }
  });
  file.command("put").description("Upload/overwrite a file in a Studio Web project").argument("<projectId>", "Project UUID").argument("<fileId>", "File UUID to overwrite").argument("<localPath>", "Local file path to upload").option("--login-validity <minutes>", "Minimum minutes before token expiration", (v) => Number.parseInt(v, 10), 10).examples(FILE_PUT_EXAMPLES).trackedAction(processContext, async (projectId, fileId, localPath2, options) => {
    const [error] = await catchError((async () => {
      const { loginStatus: loginStatus2, backendBase } = await getAuthAndBackendBase(options.loginValidity);
      const fs7 = getFileSystem();
      const absPath = fs7.path.resolve(localPath2);
      const fileBuffer = await fs7.readFile(absPath);
      if (!fileBuffer) {
        throw new Error(`File not found: ${absPath}`);
      }
      const fileName = fs7.path.basename(absPath);
      const url = `${backendBase}/api/Project/${projectId}/FileOperations/File/${fileId}`;
      const formData = new FormData;
      const blob = new Blob([fileBuffer]);
      formData.append("file", blob, fileName);
      const response = await fetch(url, {
        method: "PUT",
        headers: {
          Authorization: `Bearer ${loginStatus2.accessToken}`
        },
        body: formData
      });
      if (!response.ok) {
        const text = await response.text();
        throw new Error(`Studio Web API returned ${response.status}: ${text}`);
      }
      OutputFormatter.success({
        Result: RESULTS.Success,
        Code: "AgentFilePut",
        Data: {
          Status: "File uploaded",
          ProjectId: projectId,
          FileId: fileId,
          LocalPath: absPath
        }
      });
    })());
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to upload file",
        Instructions: error.message
      });
      processContext.exit(1);
    }
  });
};

