function createDefaultSemanticEvaluator(id) {
  const now = new Date().toISOString();
  return {
    fileName: "evaluator-default.json",
    id,
    name: "Default Evaluator",
    description: "An evaluator that uses a LLM to score the similarity of the actual output to the expected output",
    type: 5,
    category: 1,
    prompt: `As an expert evaluator, analyze the semantic similarity of these JSON contents to determine a score from 0-100. Focus on comparing the meaning and contextual equivalence of corresponding fields, accounting for alternative valid expressions, synonyms, and reasonable variations in language while maintaining high standards for accuracy and completeness. Provide your score with a justification, explaining briefly and concisely why you gave that score.
----
ExpectedOutput:
{{ExpectedOutput}}
----
ActualOutput:
{{ActualOutput}}
`,
    model: "same-as-agent",
    targetOutputKey: "*",
    createdAt: now,
    updatedAt: now
  };
}
function createDefaultTrajectoryEvaluator(id) {
  const now = new Date().toISOString();
  return {
    fileName: "evaluator-default-trajectory.json",
    id,
    name: "Default Trajectory Evaluator",
    description: "An evaluator that judges the agent based on its run history and expected behavior",
    type: 7,
    category: 3,
    prompt: `As an expert evaluator, determine how well the agent did on a scale of 0-100. Focus on if the simulation was successful and if the agent behaved according to the expected output accounting for alternative valid expressions, and reasonable variations in language while maintaining high standards for accuracy and completeness. Provide your score with a justification, explaining briefly and concisely why you gave that score.
----
UserOrSyntheticInputGivenToAgent:
{{UserOrSyntheticInput}}
----
SimulationInstructions:
{{SimulationInstructions}}
----
ExpectedAgentBehavior:
{{ExpectedAgentBehavior}}
----
AgentRunHistory:
{{AgentRunHistory}}
`,
    model: "same-as-agent",
    targetOutputKey: "*",
    createdAt: now,
    updatedAt: now
  };
}
function createDefaultEvaluationSet(opts) {
  const now = new Date().toISOString();
  return {
    fileName: "evaluation-set-default.json",
    id: opts.id,
    name: "Default Evaluation Set",
    batchSize: 10,
    evaluatorRefs: opts.evaluatorIds,
    evaluations: [],
    modelSettings: [],
    agentMemoryEnabled: false,
    agentMemorySettings: [],
    lineByLineEvaluation: false,
    createdAt: now,
    updatedAt: now
  };
}

