async function loadGuardrailDefinitions(fs7, projectPath) {
  const [readErr, raw] = await catchError(fs7.readFile(fs7.path.join(projectPath, "agent.json"), "utf-8"));
  if (readErr || raw == null) {
    return;
  }
  const [parseErr, parsed] = await catchError(Promise.resolve().then(() => JSON.parse(raw)));
  if (parseErr || !hasBuiltInGuardrail(parsed)) {
    return;
  }
  const [err3, definitions] = await catchError(getGuardrailDefinitions());
  if (err3 || definitions === undefined) {
    return;
  }
  return definitions.map(toReviewerDefinition);
}
function hasBuiltInGuardrail(parsed) {
  if (typeof parsed !== "object" || parsed === null) {
    return false;
  }
  const guardrails = parsed.guardrails;
  if (!Array.isArray(guardrails)) {
    return false;
  }
  return guardrails.some((entry) => {
    if (typeof entry !== "object" || entry === null) {
      return false;
    }
    const obj = entry;
    return obj.$guardrailType === "builtInValidator" || typeof obj.validatorType === "string";
  });
}
function toReviewerDefinition(d) {
  return {
    validator: d.validator,
    allowedScopes: d.allowedScopes,
    parameters: d.parameters.map((p) => ({
      type: p.type,
      id: p.id,
      required: p.required,
      ...p.options ? { options: p.options } : {},
      ...p.keySource ? { keySource: p.keySource } : {},
      ...p.min != null ? { min: p.min } : {},
      ...p.max != null ? { max: p.max } : {},
      ...p.step != null ? { step: p.step } : {}
    }))
  };
}

